fn require_non_empty_trimmed(field: &str, value: &str) -> AtelierResult<String> {
    handshake_ckc_moodboard::require_non_empty_trimmed(field, value)
        .map_err(AtelierError::Validation)
}

fn parse_and_validate_moodboard(raw_json_text: &str) -> AtelierResult<(Value, MoodboardDocument)> {
    handshake_ckc_moodboard::parse_and_validate_moodboard(raw_json_text)
        .map_err(AtelierError::Validation)
}

